(function(root){
const tokens=['bg','sidebar','panel','raised','hover','border','text','strong','muted','subtle','accent','accent-bg','purple'];
function theme(value){if(value?.format!=='amago-theme-v1'||typeof value.name!=='string'||!value.name.trim()||value.name.length>60)throw Error('Tema inválido: use o formato amago-theme-v1.');const colors={};for(const key of tokens){if(!/^#[0-9a-f]{6}$/i.test(value.colors?.[key]||''))throw Error('O tema precisa de uma cor hexadecimal de 6 dígitos para '+key+'.');colors[key]=value.colors[key]}return {format:value.format,id:String(value.id||value.name).replace(/[^a-z0-9-]/gi,'-').slice(0,60),name:value.name,author:String(value.author||'Comunidade').slice(0,80),mode:value.mode==='light'?'light':'dark',colors}}
function plugin(value){if(value?.format!=='amago-plugin-v1'||!/^[a-z0-9][a-z0-9-]{1,59}$/.test(value.id||'')||typeof value.name!=='string'||!value.name.trim()||value.name.length>80)throw Error('Pacote de plugin inválido.');if(typeof value.code!=='string'||value.code.length>200000)throw Error('O módulo do plugin deve ter até 200 KB.');if(!Array.isArray(value.permissions)||value.permissions.some(p=>!['note:read','note:write'].includes(p)))throw Error('Permissão não suportada.');if(!Array.isArray(value.commands)||!value.commands.length||value.commands.length>12||value.commands.some(c=>!/^[a-z0-9-]{1,40}$/.test(c.id)||typeof c.title!=='string'||!c.title||c.title.length>80)||new Set(value.commands.map(c=>c.id)).size!==value.commands.length)throw Error('Declare de 1 a 12 comandos com identificadores únicos.');return {format:value.format,id:value.id,name:value.name,version:String(value.version||'1.0.0').slice(0,30),description:String(value.description||'').slice(0,500),author:String(value.author||'Comunidade').slice(0,80),permissions:[...new Set(value.permissions)],commands:value.commands.map(c=>({id:c.id,title:c.title})),code:value.code,enabled:false}}
root.AmagoExtensions={tokens,theme,plugin};
})(globalThis);
